import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_maxpool_hardtanh_mean_tanh_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int H_in,
    int W_in,
    int K_h,
    int K_w,
    int S_h,
    int S_w,
    float hardtanh_min,
    float hardtanh_max
) {
    int batch = blockIdx.x;
    int channel = blockIdx.y;

    if (batch >= batch_size || channel >= channels) return;

    int H_out = (H_in - K_h) / S_h + 1;
    int W_out = (W_in - K_w) / S_w + 1;
    int num_windows = H_out * W_out;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    float sum = 0.0f;

    for (int i = tid; i < num_windows; i += num_threads) {
        int h_out = i / W_out;
        int w_out = i % W_out;

        int h_start = h_out * S_h;
        int w_start = w_out * S_w;

        float max_val = -INFINITY;
        for (int h = h_start; h < h_start + K_h; ++h) {
            for (int w = w_start; w < w_start + K_w; ++w) {
                if (h >= H_in || w >= W_in) continue;
                int input_idx = batch * channels * H_in * W_in +
                                channel * H_in * W_in +
                                h * W_in +
                                w;
                float val = __ldg(input + input_idx);
                max_val = fmaxf(max_val, val);
            }
        }

        float clamped = fminf(fmaxf(max_val, hardtanh_min), hardtanh_max);
        sum += clamped;
    }

    __shared__ float shared_sum[256];
    shared_sum[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float total_sum = shared_sum[0];
        float mean = total_sum / num_windows;
        float tanh_mean = tanhf(mean);
        int output_idx = batch * channels + channel;
        output[output_idx] = tanh_mean;
    }
}

torch::Tensor fused_op_cuda(
    torch::Tensor input,
    int K_h,
    int K_w,
    int S_h,
    int S_w,
    float hardtanh_min,
    float hardtanh_max
) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    auto output = torch::zeros({batch_size, channels, 1, 1}, input.options());

    dim3 grid(batch_size, channels);
    int block_size = 256;

    fused_maxpool_hardtanh_mean_tanh_kernel<<<grid, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        H_in,
        W_in,
        K_h,
        K_w,
        S_h,
        S_w,
        hardtanh_min,
        hardtanh_max
    );

    return output;
}
"""

fused_kernel_cpp = """
torch::Tensor fused_op_cuda(torch::Tensor input, int K_h, int K_w, int S_h, int S_w, float hardtanh_min, float hardtanh_max);
"""

fused_op_ext = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, maxpool_kernel_size, maxpool_stride, hardtanh_min, hardtanh_max):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.maxpool_kernel_size = maxpool_kernel_size
        self.maxpool_stride = maxpool_stride
        self.hardtanh_min = hardtanh_min
        self.hardtanh_max = hardtanh_max

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_op_ext.fused_op_cuda(
            x,
            self.maxpool_kernel_size,
            self.maxpool_kernel_size,
            self.maxpool_stride,
            self.maxpool_stride,
            self.hardtanh_min,
            self.hardtanh_max
        )
        return x
